insert into beleg_internal.products(id,name,price,description,category,image,image_note,stock,active,kind,real_photo,deleted,size,color) values
('candle-small','Жижиг үнэртэй лаа',12000,'Жижиг савтай нэг ширхэг лааны санаа. Үнэр, жин, шатах хугацааг бодит бүтээгдэхүүнээр баталгаажуулна.','candles','/assets/pexels-9651902.jpg','Жишээ загвар · Гаднын жишээ зураг, бодит барааны зураг биш. Үнийг баталгаажуулсны дараа худалдаанд гаргана.',0,false,'physical',false,false,'',''),
('candle-flower','Цэцгэн хэлбэртэй лаа',15000,'Цэцгэн хэлбэртэй чимэглэлийн лааны санаа. Зураг нь жишээ; хэлбэр, өнгө, үнэрийг баталгаажуулна.','candles','','Жишээ загвар · Гаднын жишээ зураг, бодит барааны зураг биш. Үнийг баталгаажуулсны дараа худалдаанд гаргана.',0,false,'physical',false,false,'',''),
('candle-glass','Шилэн савтай лаа',25000,'Шилэн савтай үнэртэй лааны загвар. Савны хэмжээ, үнэрийг тохируулна.','candles','/assets/pexels-8101908.jpg','Жишээ загвар · Гаднын жишээ зураг, бодит барааны зураг биш. Үнийг баталгаажуулсны дараа худалдаанд гаргана.',0,false,'physical',false,false,'',''),
('gift-bath','Лаа + ванны бөмбөлөг',39000,'Нэг лаа, ванны бөмбөлөг, мэндчилгээтэй амралтын багцын санаа. Жин, найрлага, үнэр, савлагааг батална.','gifts','/assets/pexels-6683009.jpg','Жишээ загвар · Гаднын жишээ зураг, бодит барааны зураг биш. Үнийг баталгаажуулсны дараа худалдаанд гаргана.',0,false,'physical',false,false,'',''),
('gift-letters','Open When Letters',29000,'«Санасан үедээ», «Гунигласан үедээ», «Баярласан үедээ» нээх хувийн захидлын санаа. Хэнд, ямар тохиолдолд, хэдэн захидал хүсэж байгаагаа бичнэ.','gifts','/assets/catalog/letter-box.jpg','Жишээ загвар · AI бүтээгдэхүүний жишээ зураг. Бодит бараа, бэлэн байдал баталгаажаагүй.',0,false,'physical',false,false,'',''),
('gift-voice','QR дуут бэлэг',15000,'Өөрийн дуу хоолойгоо хувийн сувгаар илгээнэ. Эзэн сонсох холбоосыг бэлтгэж, утсаар нээгдэхийг шалгаад QR карт урлана. Файлыг энэ сайтад автоматаар байрлуулахгүй.','qr','','Жишээ загвар · Гаднын жишээ зураг, бодит барааны зураг биш. Үнийг баталгаажуулсны дараа худалдаанд гаргана.',0,false,'voice',false,false,'',''),
('gift-poem','AI шүлэгтэй бэлэг',12000,'Хүлээн авагчийн нэр, баяр, дурсамж, хүссэн өнгө аясаа бичнэ. Эзэн AI-ийн тусламжтай ноорог бэлтгэж, хянуулсны дараа бэлэгт оруулна.','qr','','Жишээ загвар · Гаднын жишээ зураг, бодит барааны зураг биш. Үнийг баталгаажуулсны дараа худалдаанд гаргана.',0,false,'ai',false,false,'',''),
('love-letter-box','Хайрцагтай хайрын захидал',39000,'39,000₮ — жишиг үнэ. Энгийн тагтай картон хайрцагт багтах Open When төрлийн олон дугтуйтай хайрын захидлын санаа. Дугтуйн тоо, захидлын агуулга, хайрцгийн хэмжээг тохиролцоно. Жишээ зураг; бодит хийц, үнэ баталгаажих хүртэл захиалга авахгүй.','letters','/assets/catalog/letter-box.jpg','Жишээ загвар · AI бүтээгдэхүүний жишээ зураг. Бодит бараа биш; захиалга авахгүй.',0,false,'physical',false,false,'Хэмжээг бодит загвараар баталгаажуулна','Беж · Ягаан · Крем'),
('photo-memory-box','Дэлгэгддэг зурагтай дурсамжийн хайрцаг',45000,'45,000₮ — жишиг үнэ. Жижиг, тусдаа тагтай энгийн картон хайрцаг. Тагийг өргөхөд эвхэгдсэн зурган тууз нэг нэгээрээ сугарч дэлгэгдэнэ. Модон, нарийн механизмтай хийц биш. Зургийн тоо, хэмжээ, мэндчилгээг тохиролцоно. Зураг дахь дурсамжууд нь AI жишээ; таны хувийн зураг биш.','photo-gifts','/assets/catalog/photo-box.jpg','Жишээ загвар · AI бүтээгдэхүүний жишээ зураг. Бодит бараа биш; захиалга авахгүй.',0,false,'physical',false,false,'Хэмжээг бодит загвараар баталгаажуулна','Беж · Ягаан · Крем'),
('love-envelope-set','Дугтуйтай хайрын захидлын багц',29000,'29,000₮ — жишиг үнэ. Беж, ягаан, крем өнгийн олон дугтуй, хайртай хүндээ зориулсан хувийн захидлын багцын санаа. Дугтуйн тоо, агуулгыг тохиролцоно. Том хайрцаг шаардахгүй, туузаар боож бэлтгэх энгийн загвар. Жишээ зураг; захиалга одоогоор хаалттай.','letters','/assets/catalog/envelope-set.jpg','Жишээ загвар · AI бүтээгдэхүүний жишээ зураг. Бодит бараа биш; захиалга авахгүй.',0,false,'physical',false,false,'Хэмжээг бодит загвараар баталгаажуулна','Беж · Ягаан · Крем')
